CREATE TABLE IF NOT EXISTS leads (id text PRIMARY KEY, reference text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), name text NOT NULL, phone text NOT NULL, email text, zip text, location text, service_slug text NOT NULL, description text NOT NULL, urgency text NOT NULL, details jsonb NOT NULL, consent boolean NOT NULL, source text NOT NULL, source_page text, utm jsonb, ip_hash text NOT NULL, is_demo boolean NOT NULL, status text NOT NULL DEFAULT 'new', notification_status text NOT NULL DEFAULT 'pending', notification_attempts integer NOT NULL DEFAULT 0, notification_last_error text, notification_provider_id text, notification_last_attempt_at timestamptz, idempotency_key uuid NOT NULL UNIQUE, dedupe_hash text NOT NULL);
CREATE INDEX IF NOT EXISTS leads_created_at_idx ON leads(created_at);
CREATE INDEX IF NOT EXISTS leads_service_slug_idx ON leads(service_slug);
CREATE INDEX IF NOT EXISTS leads_dedupe_idx ON leads(dedupe_hash, created_at);
CREATE TABLE IF NOT EXISTS lead_attachments (id text PRIMARY KEY, lead_id text NOT NULL REFERENCES leads(id) ON DELETE CASCADE, name text NOT NULL, content_type text NOT NULL, data bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS lead_attachments_lead_id_idx ON lead_attachments(lead_id);
CREATE TABLE IF NOT EXISTS lead_events (id text PRIMARY KEY, lead_id text NOT NULL REFERENCES leads(id) ON DELETE CASCADE, type text NOT NULL, value text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytics_events (id text PRIMARY KEY, type text NOT NULL, page text NOT NULL, service_slug text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (key text NOT NULL, window_start timestamptz NOT NULL, count integer NOT NULL, PRIMARY KEY(key, window_start));
CREATE TABLE IF NOT EXISTS ai_usage_months (month text PRIMARY KEY, reserved integer NOT NULL DEFAULT 0, used integer NOT NULL DEFAULT 0, input_tokens bigint NOT NULL DEFAULT 0, output_tokens bigint NOT NULL DEFAULT 0, cost_usd numeric NOT NULL DEFAULT 0, model_errors integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ai_sessions (id text PRIMARY KEY, visitor_hash text NOT NULL, month text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), last_activity_at timestamptz NOT NULL DEFAULT now(), visitor_messages integer NOT NULL DEFAULT 0, counted boolean NOT NULL DEFAULT false, reservation_state text NOT NULL DEFAULT 'none', in_flight_id text, in_flight_at timestamptz);
CREATE TABLE IF NOT EXISTS ai_lead_drafts (token text PRIMARY KEY, session_id text NOT NULL REFERENCES ai_sessions(id) ON DELETE CASCADE, payload jsonb NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, confirmation_key uuid, lead_id text REFERENCES leads(id));
CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
